import React, { useState } from "react";
import axios from "axios";

function App() {
  const [query, setQuery] = useState("");
  const [answer, setAnswer] = useState("");
  const [audio, setAudio] = useState(null);
  const [loading, setLoading] = useState(false);

  // TEXT QUERY
  const handleAsk = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setAnswer("");
    setAudio(null);

    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/api/v1/rag/ask?query=${query}`
      );

      setAnswer(res.data.answer);
    } catch (err) {
      console.error(err);
      setAnswer("❌ Error fetching response");
    }

    setLoading(false);
  };

  // VOICE QUERY
  const handleVoice = async () => {
    setLoading(true);
    setAnswer("Listening... 🎤");
    setAudio(null);

    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/api/v1/voice/ask"
      );

      setAnswer(res.data.answer);

      // ✅ FIXED: use /static
      setAudio(`http://127.0.0.1:8000/static/${res.data.audio_file}`);
    } catch (err) {
      console.error(err);
      setAnswer("❌ Voice processing error");
    }

    setLoading(false);
  };

  return (
    <div style={{ padding: "40px", fontFamily: "Arial" }}>
      <h1>🇮🇳 Sarkari Saathi AI</h1>

      <input
        type="text"
        placeholder="Ask about government schemes..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        style={{ padding: "10px", width: "300px" }}
      />

      <br /><br />

      <button onClick={handleAsk} disabled={loading}>
        Ask
      </button>

      <button
        onClick={handleVoice}
        style={{ marginLeft: "10px" }}
        disabled={loading}
      >
        🎤 Voice Ask
      </button>

      <h3>Answer:</h3>

      {loading ? <p>⏳ Processing...</p> : <p>{answer}</p>}

      {audio && (
        <audio controls autoPlay>
          <source src={audio} type="audio/mpeg" />
        </audio>
      )}
    </div>
  );
}

export default App;
